class Solution {
    public int getSum(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;
            a = a ^ b;
            b = carry;
        }
        return a;
    }
}

class Solution {
    public int getSum(int a, int b) {
        if (b == 0) {
            return a;
        }
        return getSum(a ^ b, (a & b) << 1);
    }
}

class Solution {
    public int getSum(int a, int b) {
        int result = 0;
        boolean carry = false;
        int mask = 1;
        do {
            boolean bitA = (a & mask) != 0;
            boolean bitB = (b & mask) != 0;
            boolean sumBit = bitA ^ bitB ^ carry;
            if (sumBit) {
                result |= mask;
            }
            carry = (bitA && bitB) || (bitA && carry) || (bitB && carry);
            mask <<= 1;
        } while (mask != 0);
        return result;
    }
}

class Solution {
    public int getSum(int a, int b) {
        int partial = a ^ b;
        int propagate = partial;
        int generate = a & b;
        for (int shift = 1; shift < 32; shift <<= 1) {
            generate |= propagate & (generate << shift);
            propagate &= propagate << shift;
        }
        return partial ^ (generate << 1);
    }
}

class Solution {
    public int getSum(int a, int b) {
        while (b > 0) {
            a = increment(a);
            b = decrement(b);
        }
        while (b < 0) {
            a = decrement(a);
            b = increment(b);
        }
        return a;
    }

    private int increment(int value) {
        int mask = 1;
        while (mask != 0 && (value & mask) != 0) {
            value ^= mask;
            mask <<= 1;
        }
        return mask == 0 ? value : value ^ mask;
    }

    private int decrement(int value) {
        int mask = 1;
        while (mask != 0 && (value & mask) == 0) {
            value ^= mask;
            mask <<= 1;
        }
        return mask == 0 ? value : value ^ mask;
    }
}
